node -e "
const fs = require('fs');
const path = require('path');

// .plane-config.json が存在しない場合はスキップ
const configPath = path.join(process.cwd(), '.plane-config.json');
if (!fs.existsSync(configPath)) {
  process.stdout.write(JSON.stringify({ skip: true, reason: '.plane-config.json not found' }));
  process.exit(0);
}

// stdin からClineのタスク情報を読み込む
let input = '';
process.stdin.on('data', d => input += d);
process.stdin.on('end', () => {
  try {
    const ctx = JSON.parse(input || '{}');
    const taskTitle = (ctx.task && ctx.task.title) || '';

    // チケットSeqIDをタスクタイトルから抽出: 例 '[#42]' or '#42'
    const match = taskTitle.match(/#(\\d+)/);
    if (!match) {
      process.stdout.write(JSON.stringify({ skip: true, reason: 'No issue ID in task title' }));
      process.exit(0);
    }

    const issueSeq = match[1];

    // フェーズの判定（タスクタイトルから）
    let phase = 'planning';
    if (/実装|implement/i.test(taskTitle)) phase = 'implementation';
    else if (/検証|verify|test/i.test(taskTitle)) phase = 'verification';
    else if (/振り返り|reflect/i.test(taskTitle)) phase = 'reflection';

    const { execSync } = require('child_process');
    execSync(
      `bash ai-dlc/dlc-scripts/plane/task-start.sh ${issueSeq} ${phase}`,
      { stdio: 'inherit', cwd: process.cwd() }
    );
  } catch (e) {
    // Plane連携失敗はループを止めない（警告のみ）
    console.error('[plane hook] task-start failed:', e.message);
  }
  process.exit(0);
});
"

node -e "
const fs = require('fs');
const path = require('path');

// .plane-config.json が存在しない場合はスキップ
const configPath = path.join(process.cwd(), '.plane-config.json');
if (!fs.existsSync(configPath)) process.exit(0);

// .loop-env からチケット情報を取得
const loopEnvPath = path.join(process.cwd(), '.loop-env');
if (!fs.existsSync(loopEnvPath)) process.exit(0);

const loopEnv = fs.readFileSync(loopEnvPath, 'utf8');
const seqMatch = loopEnv.match(/PLANE_ISSUE_SEQ=(\\d+)/);
if (!seqMatch) process.exit(0);

const issueSeq = seqMatch[1];

let input = '';
process.stdin.on('data', d => input += d);
process.stdin.on('end', () => {
  try {
    const ctx = JSON.parse(input || '{}');
    // タスクの成否を判定
    const status = (ctx.task && ctx.task.status === 'completed') ? 'success' : 'partial';

    const { execSync } = require('child_process');
    execSync(
      `bash ai-dlc/dlc-scripts/plane/task-end.sh ${issueSeq} ${status}`,
      { stdio: 'inherit', cwd: process.cwd() }
    );
  } catch (e) {
    console.error('[plane hook] task-end failed:', e.message);
  }
  process.exit(0);
});
"
